INSERT INTO `wp_options` VALUES (954,'_transient_wpmedia_mcp_oauth_wellknown_health_check','a:6:{s:5:\"label\";s:29:\"MCP OAuth discovery documents\";s:6:\"status\";s:11:\"recommended\";s:5:\"badge\";a:2:{s:5:\"label\";s:13:\"Configuration\";s:5:\"color\";s:4:\"blue\";}s:11:\"description\";s:377:\"<p>The following .well-known discovery document(s) did not respond as expected: oauth-protected-resource, oauth-authorization-server. This does not match the confirmed .well-known/acme-challenge/ interception fingerprint, so the cause is inconclusive from this check alone (it may be a timeout, an access wall such as HTTP Basic Auth or a WAF, or a WordPress-served error).</p>\";s:7:\"actions\";s:565:\"<p>Check your error/access logs for the requests to these paths, and rule out an authentication wall (staging HTTP Basic Auth, a WAF, or bot mitigation) before assuming a routing problem.</p><p>This check runs from the server to itself. A \"Good\" result here does not guarantee external clients can reach these documents: a CDN, WAF, or reverse proxy in front of the site can still 404 these paths for external traffic while the server\'s own loopback request bypasses it. Verify with an external <code>curl</code> request after applying any server-config change.</p>\";s:4:\"test\";s:37:\"wpmedia_mcp_oauth_wellknown_discovery\";}','off');
