INSERT INTO `wp_posts` VALUES (50,1,'2026-09-07 18:57:46','2026-09-07 18:57:46','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Asmeninė fotosesija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>man – vieta, kur galiu save išreikšti pilnai. Visada žaviuosi žmonėmis, kurie nebijo spalvų, keistų pozų ar akcentų, patraukiančių akį. Man įdomu, kai nereikia visko daryti pagal vieną taisyklę. Kai galima paeksperimentuoti, ieškoti kitokio kampo ir leisti žmogui atsiskleisti ne tik išore, bet ir tuo, kas jame yra. Kartais spalvos, judesys ar viena netikėta detalė pasako kur kas daugiau nei tobulai surežisuotas kadras</p>\n<!-- /wp:paragraph -->','Fotosesijos','','publish','closed','closed','','fotosesijos','','','2026-09-26 08:46:32','2026-09-26 08:46:32','',0,'http://sada.local/?page_id=50',0,'page','',0);
