INSERT INTO `wp_posts` VALUES (80,1,'2026-09-08 17:47:31','2026-09-08 17:47:31','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Užkulisių fotografija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>leidžia pamatyti ir parodyti tai, ko ne visada pastebi kiti. Tai, kas vyksta prieš pasirodymą, tarp kadrų ar dar niekam neprasidėjus. Man patinka tos akimirkos, kai žmonės tiesiog būna savimi – ruošiasi, skuba, juokiasi, susikaupia. Ten irgi yra savotiškas grožis. Kartais net daugiau, nei atrodo iš pirmo žvilgsnio</p>\n<!-- /wp:paragraph -->','Užkuliusiai','','publish','closed','closed','','uzkuliusiai','','','2026-09-26 08:50:33','2026-09-26 08:50:33','',0,'http://sada.local/?page_id=80',0,'page','',0);
