INSERT INTO `wp_posts` VALUES (110,1,'2026-09-10 10:10:11','2026-09-10 10:10:11','<!-- wp:paragraph -->\n<p>Gyvos muzikos, scenos ir žmonių fotografija. Šviesa, judesys ir atmosfera tokie, kokie jie buvo.</p>\n<!-- /wp:paragraph -->','Koncertai','','inherit','closed','closed','','19-revision-v1','','','2026-09-10 10:10:11','2026-09-10 10:10:11','',19,'http://sada.local/?p=110',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (112,1,'2026-09-10 10:12:05','2026-09-10 10:12:05','<!-- wp:paragraph -->\n<p>Žmonės, emocijos ir detalės. Renginių fotografija, išsauganti atmosferą ir akimirkas tokias, kokios jos buvo.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Renginiai','','inherit','closed','closed','','61-revision-v1','','','2026-09-10 10:12:05','2026-09-10 10:12:05','',61,'http://sada.local/?p=112',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (113,1,'2026-09-10 10:39:33','2026-09-10 10:39:33','<!-- wp:paragraph -->\n<p><strong>Koncertų fotografija</strong> man yra gyva muzika, scena ir žmonės viename kadre. Fotografuoju atlikėjus, publiką, šviesą, judesį ir atmosferą tokius, kokie jie buvo tą akimirką.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Man svarbu ne tik užfiksuoti pasirodymą, bet ir išsaugoti jo charakterį – energiją scenoje, netikėtus momentus, žmonių reakcijas ir detales, kurios kuria visą koncerto istoriją. Fotografuoju koncertus, muzikinius renginius ir kitus gyvos muzikos projektus visoje Lietuvoje.</p>\n<!-- /wp:paragraph -->','Koncertai','','inherit','closed','closed','','19-revision-v1','','','2026-09-10 10:39:33','2026-09-10 10:39:33','',19,'http://sada.local/?p=113',0,'revision','',0);
