INSERT INTO `wp_posts` VALUES (124,1,'2026-09-10 11:36:43','2026-09-10 11:36:43','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Asmeninė fotosesija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>tai ne tik portretas, bet ir žmogaus charakteris, spalvos, nuotaika bei natūralios akimirkos viename kadre. Fotografuoju kūrybines ir portretines fotosesijas visoje Lietuvoje. Man svarbu ne dirbtinis pozavimas, o tikras žmogus, jo išraiška, judesys ir detalės, kurios padeda sukurti savitą vizualinę istoriją</p>\n<!-- /wp:paragraph -->','Fotosesijos','','inherit','closed','closed','','50-revision-v1','','','2026-09-10 11:36:43','2026-09-10 11:36:43','',50,'http://sada.local/?p=124',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (125,1,'2026-09-10 11:36:59','2026-09-10 11:36:59','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Asmeninė fotosesija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>tai ne tik portretas, bet ir žmogaus charakteris, spalvos, nuotaika bei natūralios akimirkos viename kadre. Fotografuoju kūrybines ir portretines fotosesijas visoje Lietuvoje. Man svarbu ne dirbtinis pozavimas, o tikras žmogus, jo išraiška, judesys ir detalės, kurios padeda sukurti savitą vizualinę istoriją.</p>\n<!-- /wp:paragraph -->','Fotosesijos','','inherit','closed','closed','','50-revision-v1','','','2026-09-10 11:36:59','2026-09-10 11:36:59','',50,'http://sada.local/?p=125',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (127,1,'2026-09-10 12:02:21','2026-09-10 12:02:21','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Renginių fotografija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Renginių fotografija – žmonės, emocijos ir akimirkos, kurios kuria visą renginio istoriją. Fotografuoju natūraliai, ieškodama tikrų reakcijų, judesio ir detalių.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Fotografuoju įvairius renginius visoje Lietuvoje – nuo kūrybinių ir kultūrinių projektų iki švenčių bei kitų susibūrimų. Man svarbu perteikti ne tik tai, kas vyko, bet ir atmosferą, žmones bei charakterį, dėl kurių kiekvienas renginys yra skirtingas.</p>\n<!-- /wp:paragraph -->','Renginiai','','inherit','closed','closed','','61-revision-v1','','','2026-09-10 12:02:21','2026-09-10 12:02:21','',61,'http://sada.local/?p=127',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (129,1,'2026-09-10 12:05:40','2026-09-10 12:05:40','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Užkulisių fotografija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Užkulisių fotografija atskleidžia tai, ko dažniausiai nemato žiūrovas – pasiruošimą, žmones, emocijas ir netikėtas akimirkas prieš pasirodymą ar renginį.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Fotografuoju užkulisius natūraliai ir dokumentiškai, išsaugodama tikrą proceso atmosferą. Nuo pasiruošimo ir repeticijų iki akimirkų prieš sceną ar po renginio – čia svarbios detalės, žmonių tarpusavio ryšys ir tai, kas vyksta už pagrindinio kadro.</p>\n<!-- /wp:paragraph -->','Užkuliusiai','','inherit','closed','closed','','80-revision-v1','','','2026-09-10 12:05:40','2026-09-10 12:05:40','',80,'http://sada.local/?p=129',0,'revision','',0);
