INSERT INTO `wp_posts` VALUES (141,1,'2026-09-10 13:02:22','2026-09-10 13:02:22','<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":100,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://sada.local/wp-content/uploads/2026/09/front-page-001-1024x683.jpg\" alt=\"\" class=\"wp-image-100\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":46,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://sada.local/wp-content/uploads/2026/09/koncertai-011-1-1024x683.jpg\" alt=\"Atlikėjai koncerto scenoje\" class=\"wp-image-46\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":103,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://sada.local/wp-content/uploads/2026/09/front-page-003-1024x683.jpg\" alt=\"\" class=\"wp-image-103\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->','Pradžia','','inherit','closed','closed','','97-revision-v1','','','2026-09-10 13:02:22','2026-09-10 13:02:22','',97,'http://sada.local/?p=141',0,'revision','',0);
