INSERT INTO `wp_posts` VALUES (144,1,'2026-09-26 08:43:11','2026-09-26 08:43:11','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Koncertų fotografija </h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>man yra numeris vienas iš mėgstamiausių dalykų fotografijoje. Čia nereikia nieko statyti, modeliuoti ar aiškinti, kaip stovėti. Turi pats prisitaikyti prie aplinkos, žmonių, šviesų ir to, kas vyksta prieš akis. Su kamera bandai pamatyti kažką kitaip, pagauti sekundę, kurios galbūt niekas kitas nepastebėjo. Man patinka tas chaosas, judėjimas ir jausmas, kad niekada iki galo nežinai, ką parsineši iš renginio</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Koncertai','','inherit','closed','closed','','19-revision-v1','','','2026-09-26 08:43:11','2026-09-26 08:43:11','',19,'http://sada.local/?p=144',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (145,1,'2026-09-26 08:43:34','2026-09-26 08:43:34','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Koncertų fotografija </h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>man yra numeris vienas iš mėgstamiausių dalykų fotografijoje. Čia nereikia nieko statyti, modeliuoti ar aiškinti, kaip stovėti. Turi pats prisitaikyti prie aplinkos, žmonių, šviesų ir to, kas vyksta prieš akis. Su kamera bandai pamatyti kažką kitaip, pagauti sekundę, kurios galbūt niekas kitas nepastebėjo. Man patinka tas chaosas, judėjimas ir jausmas, kad niekada iki galo nežinai, ką parsineši iš renginio</p>\n<!-- /wp:paragraph -->','Koncertai','','inherit','closed','closed','','19-revision-v1','','','2026-09-26 08:43:34','2026-09-26 08:43:34','',19,'http://sada.local/?p=145',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (146,1,'2026-09-26 08:44:24','2026-09-26 08:44:24','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Renginių fotografija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>man atrodo toks svarbus ir įdomus dalykas būtent dėl to, kad niekada nežinai, kas tavęs laukia. Kiekvienas turi savo tempą, žmones, energiją ir mažus momentus, kurie nutinka visai netikėtai. Patinka būti ten, kur kažkas vyksta, ir visa tai pamatyti savaip. Ne tik tai, kas suplanuota, bet ir tai, kas atsiranda tarp visko</p>\n<!-- /wp:paragraph -->','Renginiai','','inherit','closed','closed','','61-revision-v1','','','2026-09-26 08:44:24','2026-09-26 08:44:24','',61,'http://sada.local/?p=146',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (147,1,'2026-09-26 08:46:29','2026-09-26 08:46:29','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Asmeninė fotosesija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>man – vieta, kur galiu save išreikšti pilnai. Visada žaviuosi žmonėmis, kurie nebijo spalvų, keistų pozų ar akcentų, patraukiančių akį. Man įdomu, kai nereikia visko daryti pagal vieną taisyklę. Kai galima paeksperimentuoti, ieškoti kitokio kampo ir leisti žmogui atsiskleisti ne tik išore, bet ir tuo, kas jame yra. Kartais spalvos, judesys ar viena netikėta detalė pasako kur kas daugiau nei tobulai surežisuotas kadras</p>\n<!-- /wp:paragraph -->','Fotosesijos','','inherit','closed','closed','','50-revision-v1','','','2026-09-26 08:46:29','2026-09-26 08:46:29','',50,'http://sada.local/?p=147',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (148,1,'2026-09-26 08:47:23','2026-09-26 08:47:23','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Užkulisių fotografija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>leidžia pamatyti ir parodyti tai, ko ne visada pastebi kiti. Tai, kas vyksta prieš pasirodymą, tarp kadrų ar dar niekam neprasidėjus. Man patinka tos akimirkos, kai žmonės tiesiog būna savimi – ruošiasi, skuba, juokiasi, susikaupia. Ten irgi yra savotiškas grožis. Kartais net daugiau, nei atrodo iš pirmo žvilgsnio</p>\n<!-- /wp:paragraph -->','Užkuliusiai','','inherit','closed','closed','','80-revision-v1','','','2026-09-26 08:47:23','2026-09-26 08:47:23','',80,'http://sada.local/?p=148',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (149,1,'2026-09-26 08:52:00','2026-09-26 08:52:00','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vestuvių fotografija</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>meilės šventė. Tokia jautri, bet tuo pačiu pilna džiaugsmo, artumo ir gražių akimirkų. Visada jaudinuosi važiuodama fotografuoti, bet į tokias šventes turbūt labiausiai. Čia tiek daug tikrų emocijų, žmonių ir mažų detalių, kurios tą dieną paverčia sava. Man gražu ne tik tai, kas vyksta pačiame centre, bet ir žvilgsniai, prisilietimai, juokas bei visa tai, kas lieka tarp didžiųjų momentų.</p>\n<!-- /wp:paragraph -->','Vestuvės','','publish','closed','closed','','vestuves','','','2026-09-26 09:14:46','2026-09-26 09:14:46','',0,'http://sada.local/?page_id=149',0,'page','',0);
